        result = {}
        for u, distance in distances.items():
            for v, weight in costs[u].items():
                candidate = distance + weight
                old = result.get(v)
                if old is None or candidate < old:
                    result[v] = candidate
        return result

    distances = {source: 0}

    if k <= n:
        for step in range(k):
            updated = advance(distances, matrix)
            if updated == distances:
                break
            distances = updated
        return distances.get(target)

